var baseDir = "/safedir"

func getLsResult(dirPath string) (string, error) {
    cleaned := filepath.Clean(dirPath)

    resolvedPath, err := filepath.Abs(cleaned)
    if err != nil {
        return "", fmt.Errorf("failed to resolve absolute path: %w", err)
    }

    if !strings.HasPrefix(resolvedPath, baseDir) {
        return "", fmt.Errorf("path not within allowed directory")
