	for _, r := range username {
		if (r >= 'a' && r <= 'z') ||
		   (r >= 'A' && r <= 'Z') ||
		   (r >= '0' && r <= '9') ||
		   r == '_' || r == '-' || r == '.' || r == ' ' {
