package main

import (
	"crypto/sha256"
	"encoding/hex"
	"github.com/ChrisTrenkamp/goxpath"
	"github.com/ChrisTrenkamp/goxpath/tree"
	"github.com/ChrisTrenkamp/goxpath/tree/xmltree"
	"golang.org/x/crypto/bcrypt"
)

func getStudentInfo(xmlData, username, password string) (string, string, string) {
	// Parse the XML data into a document with secure options
	doc := xmltree.NewDocument()
	// Disable DTD and external entities to prevent XXE attacks
	if err := doc.ParseXMLWithOptions(xmlData, xmltree.DisallowDTD, xmltree.DisallowExternalEntities); err != nil {
		return "", "", ""
	}

	// Create a tree from the document
	t := tree.New(doc)

	// Escape username to prevent XPath injection
	usernameEscaped := xpath.Escape(username)
	query := xpath.Format("/students/student[username='%s']", usernameEscaped)

	// Execute the XPath query
	nodeset := t.Query(query)

	if len(nodeset) == 0 {
		return "", "", ""
	}

	studentNode := nodeset[0]

	// Extract password element and get stored hash
	passwordElement := studentNode.SelectSingleNode("password")
	if passwordElement == nil {
		return "", "", ""
	}
	storedHash := passwordElement.Text()

	// Use bcrypt for secure password comparison
	err := bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(password))
	if err != nil {
		return "", "", ""
	}

	// Extract name element
	nameElement := studentNode.SelectSingleNode("name")
	name := nameElement.Text()

	// Extract citizenship element
	citizenshipElement := studentNode.SelectSingleNode("citizenship")
	citizenship := citizenshipElement.Text()

	// Extract age element
	ageElement := studentNode.SelectSingleNode("age")
	age := ageElement.Text()

	return name, age, citizenship
}

