import (
	"fmt"
	"strings"
	"time"
)

/**
 * Generates a log entry for a received user message with the current timestamp,
 * in the format '[<timestamp_iso_format>] Received: <msg>'.
 *
 * @param msg The user message received. If nil, defaults to "undefined".
 * @return The log entry for the received message.
 */
func generate_receive_log(msg *string) string {
	var sanitizedMsg string
	if msg == nil {
		sanitizedMsg = "undefined"
	} else {
		replacements := map[string]string{
			"\n": "_",
			"\r": "_",
			"\t": "_",
			"]":  "_",
			"%":  "%%", // Escape percent signs to prevent format issues
		}
		temp := *msg
		for k, v := range replacements {
			temp = strings.ReplaceAll(temp, k, v)
		}
		if len(temp) > 1024 {
			temp = temp[:1024] + "..."
		}
		sanitizedMsg = temp
	}

	currentTimestamp := time.Now().ISOFormat()
	logEntry := fmt.Sprintf("[%s] Received: %s", currentTimestamp, sanitizedMsg)
	return logEntry
}

