    pemBlock := &pem.Block{
        Type:  "EC PRIVATE KEY",
        Bytes: pkcs8,
    }
    pemBytes := pem.EncodeToMemory(pemBlock)
    if pemBytes == nil {
        return "", fmt.Errorf("failed to encode ECDSA key as PEM")
    }

    return string(pemBytes), nil
}

