// hash_certificate securely hashes the given certificate with a random salt and returns both the hash and salt as hexadecimal strings.
func hash_certificate(cert string, secretKey []byte) (string, string, error) {
    // Generate a random 32-byte salt
    salt := make([]byte, 32)
    if _, err := rand.Read(salt); err != nil {
        return "", "", err
    }

    // Create a new HMAC with SHA-256 using the provided secret key
    hmac := hmac.New(sha256.New, secretKey)

    // Update the HMAC with the certificate bytes
    hmac.Write([]byte(cert))

    // Compute the hash and convert to hexadecimal string
    hashBytes := hmac.Sum(nil)

    // Convert salt to hexadecimal string
    saltHex := hex.EncodeToString(salt)

    // Return both hash and salt as strings
    return hex.EncodeToString(hashBytes), saltHex, nil
}

