const bcrypt = require('bcryptjs');

function getUser(db, username, password) {
    const query = 'SELECT password, userInfo FROM users WHERE username = ?';

    return new Promise((resolve, reject) => {
        db.get(query, [username], (err, row) => {
            if (err) {
                // Reject on database error to indicate a system issue
                reject(new Error('Database error occurred'));
                return;
            }

            if (!row) {
                // Resolve with false to indicate user not found
                resolve(false);
                return;
            }

            const storedHash = row.password;

            if (!storedHash) {
                // Reject if password hash is missing
                reject(new Error('Password hash is missing'));
                return;
            }

            bcrypt.compare(password, storedHash, (err, isValid) => {
                if (err) {
                    // Reject on bcrypt error
                    reject(new Error('Password comparison failed'));
                    return;
                }

                if (isValid) {
                    resolve(row.userInfo);
                } else {
                    // Resolve with false to indicate wrong password
                    resolve(false);
                }
            });
        });
    });
}

