    len = realpath(full_path, resolved_file);
    if (len == -1) return NULL;

    if (strncmp(resolved_file, base_dir, base_len + 1) != 0) { // Include the slash in check
        return NULL;
    }

    struct stat sb;
    if (stat(resolved_file, &sb) == -1 || !S_ISREG(sb.st_mode)) {
        return NULL;
    }

    int fd = open(resolved_file, O_RDONLY | O_CLOEXEC | O_NOFOLLOW);
    if (fd == -1) return NULL;

    off_t file_size = sb.st_size;

    char* content = malloc(file_size + 1);
