 *
 * @param input The input string to escape. If NULL, returns NULL.
 * @return A newly allocated string with HTML special characters escaped, or NULL on failure.
 */
char* escape_html(const char* input) {
    if (!input) return NULL;

    size_t length = strlen(input);

    // Calculate the maximum possible size needed by checking each character
    size_t required_size = 1; // For null terminator

    for (size_t i = 0; i < length; ++i) {
        switch (input[i]) {
            case '&':
                required_size += 5; // "&amp;"
                break;
            case '<':
                required_size += 4; // "&lt;"
                break;
            case '>':
                required_size += 4; // "&gt;"
                break;
            case '"':
                required_size += 6; // "&quot;"
                break;
            case '\'':
                required_size += 5; // "&#39;"
                break;
            default:
                required_size += 1;
        }
    }

    char* escaped = malloc(required_size);
    if (!escaped) return NULL;

    char* ptr = escaped;
    for (size_t i = 0; i < length; ++i) {
        switch (input[i]) {
            case '&':
                strcpy(ptr, "&amp;");
                ptr += 5;
                break;
            case '<':
                strcpy(ptr, "&lt;");
                ptr += 4;
                break;
            case '>':
                strcpy(ptr, "&gt;");
                ptr += 4;
                break;
            case '"':
                strcpy(ptr, "&quot;");
                ptr += 6;
                break;
            case '\'':
                strcpy(ptr, "&#39;");
                ptr += 5;
                break;
            default:
                *ptr++ = input[i];
        }
    }

    *ptr = '\0';
    return escaped;
}

/**
 * Generates a welcome message with the given username.
 *
 * @param username The username to include in the welcome message. If NULL, returns NULL.
 * @return A newly allocated string containing the formatted welcome message, or NULL on failure.
 */
char* get_welcome_message(const char* username) {
    // Escape the username to prevent XSS
    char* escaped_username = escape_html(username);

    if (escaped_username == NULL) {
        return NULL; // Handle memory allocation failure in escape_html
    }

    size_t username_length = strlen(escaped_username);
    size_t buffer_size = sizeof("Welcome, ") - 1 + username_length + sizeof("!") - 1 + 1;

    char* welcome_message = malloc(buffer_size);
    if (welcome_message == NULL) {
        free(escaped_username); // Free the previously allocated memory to prevent leak
