// Execute command using fork() and execve() for better security
char* execute_command(const char* command) {
    // Sanitize and split the command into arguments
    size_t cmd_len = strlen(command);
    char* args[256];

    // Simple command splitting (assumes no spaces in filenames)
    args[0] = strtok((char*)command, " ");
    args[1] = strtok(NULL, " ");
    args[2] = NULL;

    pid_t pid = fork();
    if (pid == -1) {
        return NULL;
    }

    if (pid == 0) {
        // Child process: execute the command
        execve(args[0], args, NULL);
        _exit(127); // Exit with error if execve fails
    } else {
        // Parent process: wait for child to finish
        int status;
        while(waitpid(pid, &status, 0) == -1 && errno == EINTR);

        if (WIFEXITED(status)) {
            char* result = malloc(256);
            snprintf(result, sizeof(char)*256, "Command exited with status %d", WEXITSTATUS(status));
