    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {0};

    // Validate the key length to be exactly 32 bytes (256 bits)
    if (key == NULL || key_len != 32) {
        return result;
    }

    // Allocate memory for IV
    result.iv = malloc(AES_BLOCK_SIZE);
    if (!result.iv) {
        return result;
    }

    // Generate random IV using cryptographically secure PRNG
    if (RAND_bytes(result.iv, AES_BLOCK_SIZE) != 1) {
        free(result.iv);
        return result;
    }

    // Create and initialize EVP encryption context
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new(cipher);
    if (!ctx) {
        free(result.iv);
        return result;
    }

    // Initialize encryption context with key and IV
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, result.iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(result.iv);
        return result;
    }

    // Allocate memory for encrypted data with padding consideration
    size_t data_len_padded = data_len + (AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE));
    size_t max_encrypted_len = data_len_padded + AES_BLOCK_SIZE;  // Account for final block
    result.encrypted_data = malloc(max_encrypted_len);
    if (!result.encrypted_data) {
        EVP_CIPHER_CTX_free(ctx);
        free(result.iv);
        return result;
    }

    // Perform encryption
    size_t encrypted_len = 0;
    if (EVP_EncryptUpdate(ctx, result.encrypted_data, &encrypted_len, data, data_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(result.iv);
        free(result.encrypted_data);
        return result;
    }

    // Allocate buffer for final encryption block
    unsigned char final_buffer[AES_BLOCK_SIZE];
    size_t final_len = 0;

    // Finalize encryption to apply padding
    if (EVP_EncryptFinal_ex(ctx, final_buffer, &final_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(result.iv);
        free(result.encrypted_data);
        return result;
    }

    // Copy final encrypted bytes to result buffer
    memcpy(result.encrypted_data + encrypted_len, final_buffer, final_len);
    encrypted_len += final_len;

    // Update the actual encrypted length
    result.encrypted_len = encrypted_len;

    // Clean up
    EVP_CIPHER_CTX_cleanup(ctx);
    EVP_CIPHER_CTX_free(ctx);

    return result;
}

