typedef struct {
    unsigned char* encrypted_data;
    size_t encrypted_len;
    unsigned char* iv;
} encryption_result;

encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {0};

    // Generate random IV and check for success
    result.iv = malloc(AES_BLOCK_SIZE);
    if (!result.iv) return result;
    if (RAND_bytes(result.iv, AES_BLOCK_SIZE) != 1) {
        free(result.iv);
        return result;
    }

    // Derive key from provided key bytes using first 128 bits (16 bytes) for AES-128
    size_t key_size = 16; // Using AES-128 bit key (16 bytes)
    if (key_len < key_size) {
        OPENSSL_cleanse(result.iv, AES_BLOCK_SIZE);
        free(result.iv);
        return result;
    }

    unsigned char derived_key[key_size];
    memcpy(derived_key, key, key_size);

    AES_KEY aes_key;
    if (AES_set_encrypt_key(derived_key, 8 * key_size, &aes_key) != 0) {
        OPENSSL_cleanse(result.iv, AES_BLOCK_SIZE);
        free(result.iv);
        OPENSSL_cleanse(derived_key, sizeof(derived_key));
        return result;
    }

    // Calculate required buffer size for encrypted data (including padding)
    size_t padded_data_len = data_len + (AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE));

    // Allocate memory for encrypted data
    result.encrypted_data = malloc(padded_data_len);
    if (!result.encrypted_data) {
        OPENSSL_cleanse(result.iv, AES_BLOCK_SIZE);
        free(result.iv);
        OPENSSL_cleanse(&aes_key, sizeof(aes_key));
        OPENSSL_cleanse(derived_key, sizeof(derived_key));
        return result;
    }

    // Copy plaintext data to encrypted buffer
    memcpy(result.encrypted_data, data, data_len);

    // Apply PKCS#7 padding
    size_t padding_length = AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE);
    if (padding_length > 0) {
        memset(result.encrypted_data + data_len, padding_length, padding_length);
    }

    // Perform AES-CBC encryption
    AES_cbc_encrypt(
        result.encrypted_data,
        result.encrypted_data,
        padded_data_len,
        &aes_key,
        result.iv,
        AES_ENCRYPT
    );

    // Clean up sensitive key material and IV
    OPENSSL_cleanse(&aes_key, sizeof(aes_key));
    OPENSSL_cleanse(derived_key, sizeof(derived_key));

    result.encrypted_len = padded_data_len;

    return result;
}

