char* write_results(const char* results) {
    // Create a temporary file with unique name
    char template[] = "/tmp/mytempXXXXXX";
    int fd = mkstemp(template);

    if (fd == -1) {
        return NULL;
    }

    // Set appropriate permissions
    if (fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
        close(fd);
        return NULL;
    }

    // Allocate memory for the filename string
    size_t len = strlen(template);
    char* filename = malloc(len + 1);
    if (!filename) {
        close(fd);
        return NULL;
    }
    strcpy(filename, template);

    // Write results to the temporary file with partial write handling
    const char* data = results;
    size_t bytes_remaining = strlen(results);
    while (bytes_remaining > 0) {
        ssize_t bytes_written = write(fd, data, bytes_remaining);
        if (bytes_written == -1) {
            free(filename);
            close(fd);
            return NULL;
        }
        data += bytes_written;
        bytes_remaining -= bytes_written;
    }

    // Close the file descriptor
    close(fd);

    return filename;
}

