static bool is_valid_subdomain(const char* sub) {
    if (sub == NULL || *sub == '\0') return false;

    int len = strlen(sub);
    if (len < 1 || len > 253) return false;

    const char* start = sub;
    const char* end = sub + len;

    while (start < end) {
        // Check for leading hyphen
        if (*start == '-') return false;

        int part_len = 0;
        while (start < end && *start != '.' && part_len < 63) {
            if (!isalnum(*start) && *start != '-') return false;
            start++;
            part_len++;
        }
        if (part_len == 0 || part_len > 63) return false;

        // Check for trailing hyphen before the dot or end
        if (start < end && *start == '.') {
            if (*(start - 1) == '-') return false; // Trailing hyphen
            start++;
            if (start == end) return false; // Ends with a dot
        } else {
            // If it's the last part, check for trailing hyphen
            if (*start == '-') return false;
            break;
        }
    }

    return true;
}

static bool is_valid_domain(const char* dom) {
    if (dom == NULL || *dom == '\0') return false;

    int len = strlen(dom);
    if (len < 1 || len > 253) return false;

    const char* start = dom;
    const char* end = dom + len;

    while (start < end) {
        // Check for leading hyphen
        if (*start == '-') return false;

        int part_len = 0;
        while (start < end && *start != '.' && part_len < 63) {
            if (!isalnum(*start) && *start != '-') return false;
            start++;
            part_len++;
        }
        if (part_len == 0 || part_len > 63) return false;

        // Check for trailing hyphen before the dot or end
        if (start < end && *start == '.') {
            if (*(start - 1) == '-') return false; // Trailing hyphen
            start++;
            if (start == end) return false; // Ends with a dot
        } else {
            // If it's the last part, check for trailing hyphen
            if (*start == '-') return false;
            break;
        }
    }

    return true;
}

char* get_url_to_visit(const char* domain, const char* subdomain_prefix) {
    bool sub_valid = (subdomain_prefix != NULL && *subdomain_prefix != '\0' && is_valid_subdomain(subdomain_prefix));

    // Check if using subdomain would exceed the buffer
    if (sub_valid) {
        size_t sub_len = strlen(subdomain_prefix);
        size_t dom_len = strlen(domain);
        size_t required_sub = 8 + 1 + sub_len + dom_len; // "https://sub.domain" including null terminator
        if (required_sub > MAX_URL_LENGTH - 1) { 
            sub_valid = false;
        }
    }

    // If not using subdomain or it's invalid, check if domain alone fits and is valid
    bool dom_valid = is_valid_domain(domain);
