    rc = sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        sqlite3_finalize(stmt);
        return NULL;
    }

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW && rc != SQLITE_DONE) {
        sqlite3_finalize(stmt);
        return NULL;
    }

    if (rc == SQLITE_DONE) {
        sqlite3_finalize(stmt);
        return NULL;
    }

    const unsigned char *stored_hash = sqlite3_column_text(stmt, 0);
    if (stored_hash == NULL) {
        sqlite3_finalize(stmt);
        return NULL;
    }

    const unsigned char *user_info = sqlite3_column_text(stmt, 1);
    if (user_info == NULL) {
        sqlite3_finalize(stmt);
        return NULL;
    }

    if (bcrypt_verify(password, stored_hash, NULL)) {
        char *result = strdup((const char *)user_info);
        sqlite3_finalize(stmt);
        return result;
    } else {
        sqlite3_finalize(stmt);
        return NULL;
    }
}

