        for (char c : filename) {
            if (!( (c >= 'a' && c <= 'z') ||
                   (c >= 'A' && c <= 'Z') ||
                   (c >= '0' && c <= '9') ||
                   c == '_' || c == '.' || c == '-') ) {
                return false;
            }
        }

        // Ensure the filename doesn't end with a dot
        if (!filename.empty() && filename.back() == '.') return false;

        // Check for null bytes in the filename
        if (filename.find('\0') != std::string::npos) {
            return false;
        }

        return true;
    }

    bool is_within_base(const std::filesystem::path& path, const std::filesystem::path& base) {
        try {
            std::filesystem::path normalized_path = std::filesystem::lexically_normalize(path);
            std::filesystem::path normalized_base = std::filesystem::lexically_normalize(base);

            // Ensure both paths are absolute
            if (!normalized_path.is_absolute() || !normalized_base.is_absolute()) {
                return false;
            }

            return normalized_path.string().find(normalized_base.string() + "/") == 0 ||
                   normalized_path == normalized_base;
        } catch (const std::filesystem::filesystem_error&) {
            return false;
        }
    }
}

