std::string normalize_path(const std::string& path) {
    string normalized;
    size_t pos = 0;
    bool last_was_slash = false;

    for (char c : path) {
        if (c == '/') {
            if (!last_was_slash && !normalized.empty()) {
                normalized += '/';
            }
            last_was_slash = true;
        } else if (c == '.') {
            size_t next_pos = path.find('/', pos + 1);
            if (next_pos != string::npos) {
                if (path.substr(pos + 1, next_pos - pos - 1) == "..") {
                    // Handle '..'
                    size_t last_slash = normalized.find_last_of('/');
                    if (last_slash != string::npos) {
                        normalized.erase(last_slash);
                    }
                    pos = next_pos;
                    continue;
                } else {
                    normalized += c;
                }
            } else {
                normalized += c;
            }
        } else {
            normalized += c;
            last_was_slash = false;
        }
        pos++;
    }

    if (normalized.empty()) {
        return ".";
    }

    // Remove trailing slash
    if (!normalized.empty() && normalized.back() == '/') {
        normalized.pop_back();
    }

    return normalized;
}

std::string getAbsolutePathWithoutResolvingSymlinks(const std::string& path) {
    if (path.empty()) {
        return "";
    }

    string result;
    if (path[0] == '/') {
        result = path;
    } else {
        char cwd[PATH_MAX];
        getcwd(cwd, sizeof(cwd));
        result = string(cwd) + "/" + path;
    }

    // Normalize the path to resolve . and ..
    return normalize_path(result);
