    if (stat(abs_dest.c_str(), &sb) != 0 || !S_ISDIR(sb.st_mode)) {
        cerr << "Destination path does not exist or is not a directory." << endl;
        return false;
    }

    // Open the archive
    a = archive_read_new();
    if (!a) {
        cerr << "Failed to allocate archive object." << endl;
        return false;
    }

    r = archive_read_open_filename(a, tar_path.c_str(), 1024);
    if (r != ARCHIVE_OK && r != ARCHIVE_END) {
        cerr << "Failed to open archive file: " << archive_error_string(a, r) << endl;
        archive_read_close(a);
        archive_read_free(a);
        return false;
    }

    while (true) {
        r = archive_read_next_header(a, &entry);
        if (r == ARCHIVE_END) {
            break;
        }
        if (r != ARCHIVE_OK && r != ARCHIVE_EOF) {
            cerr << "Archive error: " << archive_error_string(a, r) << endl;
            archive_read_close(a);
            archive_read_free(a);
