void saveSecretFile(const std::string& directory, const std::string& filename, const std::string& content) {
    // Sanitize the directory path to prevent path traversal
    char resolved_dir[PATH_MAX];
    if (realpath(directory.c_str(), resolved_dir) == nullptr) {
        throw std::runtime_error("Invalid directory path");
    }
    std::string safe_directory(resolved_dir);

    struct stat st;
    if (stat(safe_directory.c_str(), &st) != 0) {
        // Create the directory with secure permissions
        if (mkdir(safe_directory.c_str(), S_IRWXU | S_ISVTX) != 0) {
            throw std::runtime_error("Failed to create directory");
        }
    } else {
        // Ensure existing directory has correct permissions and is not a symlink
        if (chmod(safe_directory.c_str(), S_IRWXU | S_ISVTX) != 0) {
            throw std::runtime_error("Failed to set directory permissions");
        }
        struct stat current;
        if (lstat(safe_directory.c_str(), &current) != 0 || S_ISLNK(current.st_mode)) {
            throw std::runtime_error("Directory is a symbolic link");
        }
    }

    // Sanitize the filename by resolving it within the directory
    char resolved_file[PATH_MAX];
    snprintf(resolved_file, sizeof(resolved_file), "%s/%s", safe_directory.c_str(), filename.c_str());
    if (realpath(resolved_file, resolved_file) == nullptr) {
        throw std::runtime_error("Invalid filename");
    }
    // Ensure the resolved file is under the safe directory
    if (strncmp(resolved_file, safe_directory.c_str(), strlen(safe_directory.c_str())) != 0 ||
        resolved_file[strlen(safe_directory.c_str())] != '/') {
        throw std::runtime_error("Filename path traversal attempt detected");
    }
    std::string full_path = resolved_file;

    // Open the file with exclusive access to prevent race conditions
    int fd = open(full_path.c_str(), O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        if (errno == EEXIST) {
            // Check if the existing file is safe to truncate
            struct stat sb;
            if (lstat(full_path.c_str(), &sb) != 0 || S_ISLNK(sb.st_mode)) {
                throw std::runtime_error("Existing file is a symbolic link");
            }
            // Open without O_EXCL and truncate
            fd = open(full_path.c_str(), O_WRONLY | O_TRUNC);
            if (fd == -1) {
                throw std::runtime_error("Failed to open existing file");
            }
        } else {
            throw std::runtime_error("Failed to create file");
        }
    }

    // Write content securely
    ssize_t bytes_written = write(fd, content.c_str(), content.size());
    if (bytes_written != static_cast<ssize_t>(content.size())) {
        close(fd);
        throw std::runtime_error("Failed to write all bytes to file");
    }

    close(fd);

    // Ensure permissions are set correctly
    if (chmod(full_path.c_str(), S_IRUSR | S_IWUSR) != 0) {
        throw std::runtime_error("Failed to set file permissions");
    }
}

