std::string pbkdf2(const std::string& password, const std::string& salt, 
                  int iterations = 100000, int keyLength = 32) {
    unsigned char* key = new unsigned char[keyLength];
    PKCS5_PBKDF2_HMAC(password.c_str(), password.size(),
                      (const unsigned char*)salt.c_str(), salt.size(),
                      iterations, EVP_sha256(), key);

