func generatePositiveRandomNumberWithOffset(offset int) (int, error) {
    maxInt := math.MaxInt64
    n := big.NewInt(int64(maxInt))
    n = n.Sub(n, big.NewInt(1)) // Now n is maxInt - 1

    randomNumber, err := rand.Int(rand.Reader, n)
