 */
char* allocate_buffer_and_write(size_t buf_size) {
    // Ensure minimum size is met
    if (buf_size < 20) {
        return NULL;
    }

    // Maximum allowed size
    const size_t MAX_SIZE = 1024 * 1024; // 1MB
    if (buf_size > MAX_SIZE) {
        return NULL;
    }

    char* buffer = malloc(buf_size);
    if (!buffer) {
        return NULL;
    }

    // Initialize entire buffer to 'A' for security
    memset(buffer, 'A', buf_size);

    // Write first 10 bytes again (redundant but explicit)
    memset(buffer, 'A', 10);

    // Write last 10 bytes
    size_t last_ten_offset = buf_size - 10;
    if (last_ten_offset >= 0) {
        memset(buffer + last_ten_offset, 'A', 10);
    }

    return buffer;
}

