#include <string.h>

void trim_trailing_spaces(char *str) {
    if (str == NULL) {
        return;
    }
    if (*str == '\0') {
        return;
    }

    size_t len = strlen(str);
    char *p = str + len - 1;

    while (p >= str && *p == ' ') {
        p--;
    }

    if (p < str) { // All characters are spaces
        *str = '\0';
    } else {
        *(p + 1) = '\0';
    }
}
